/**
 * Python-flavoured exception objects.
 *
 * The original program lets exceptions escape `main()`, so CPython prints a
 * traceback and exits with status 1.  To reproduce that byte for byte we need
 * to carry the exception *type name*, its *message* and the chain of stack
 * frames that CPython would have shown.
 */

/** A frame as CPython's traceback module would render it. */
export function frame({ file, line, func, text = null, prefix = null, expr = null, suffix = '' }) {
  return { file, line, func, text, prefix, expr, suffix };
}

/** Base class for every emulated Python exception. */
export class PyException extends Error {
  /**
   * @param {string} type    exception class name, e.g. "ValueError"
   * @param {string} message the `str(exc)` text
   */
  constructor(type, message) {
    super(message === '' ? type : `${type}: ${message}`);
    this.pyType = type;
    this.pyMessage = message;
    /** Frames between `main()` and the raise site, outermost first. */
    this.pyTraceback = [];
  }

  /** The final `Type: message` line of a traceback. */
  get exceptionLine() {
    return this.pyMessage === '' ? this.pyType : `${this.pyType}: ${this.pyMessage}`;
  }

  /** Attach frames (outermost first) unless a deeper handler already did. */
  withTraceback(frames) {
    if (this.pyTraceback.length === 0) this.pyTraceback = frames;
    return this;
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyException {
  constructor(message) {
    super('TypeError', message);
  }
}

export class PyMemoryError extends PyException {
  constructor(message = '') {
    super('MemoryError', message);
  }
}

/**
 * `SystemExit`, raised by `argparse` through `parser.exit()` / `parser.error()`.
 * It is *not* reported as an unhandled exception, it merely sets the status.
 */
export class SystemExit extends Error {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

