/**
 * `argparse.HelpFormatter`: usage lines, the options section, and the wrapping
 * rules both of them obey.
 */

import { terminalColumns } from './terminal.mjs';

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const USAGE_PREFIX = 'usage: ';

/**
 * `HelpFormatter._format_usage`'s part splitter: bracketed or parenthesised
 * groups stay together, everything else splits on whitespace.
 */
const PART_PATTERN = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

function splitUsageParts(text) {
  return text.match(PART_PATTERN) ?? [];
}

/** Greedy word wrap, equivalent to `textwrap.wrap` for help strings. */
function wrapText(text, width) {
  const words = text.replace(/[\t\n\x0b\f\r ]+/g, ' ').trim().split(' ').filter(Boolean);
  if (words.length === 0) return [];
  const lines = [];
  let current = words[0];
  for (const word of words.slice(1)) {
    if (current.length + 1 + word.length <= width) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }
  lines.push(current);
  return lines;
}

/** `[-h]` for a flag, `--a A` for a store action, brackets when optional. */
export function formatActionUsage(action) {
  const optionString = action.optionStrings[0];
  const body = action.takesValue ? `${optionString} ${action.metavar}` : optionString;
  return action.required ? body : `[${body}]`;
}

/** `-h, --help` / `--a A`: how an action is announced in the options list. */
export function formatActionInvocation(action) {
  if (!action.takesValue) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

export class HelpFormatter {
  /** @param {string} prog program name shown in the usage line */
  constructor(prog) {
    this.prog = prog;
    this.width = terminalColumns() - 2;
  }

  /** `_format_usage`, including the two wrapping strategies argparse uses. */
  formatUsage(actions) {
    const prefix = USAGE_PREFIX;
    const optionals = actions.map(formatActionUsage).join(' ');
    let usage = [this.prog, optionals].filter((piece) => piece.length > 0).join(' ');
    const textWidth = this.width;

    if (prefix.length + usage.length > textWidth) {
      const optParts = splitUsageParts(optionals);
      const getLines = (parts, indent, linePrefix) => {
        const lines = [];
        let line = [];
        let lineLength = (linePrefix !== null ? linePrefix.length : indent.length) - 1;
        for (const part of parts) {
          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLength = indent.length - 1;
          }
          line.push(part);
          lineLength += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
        return lines;
      };

      let lines;
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        // Short program name: the first option group shares its line.
        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
        lines = optParts.length > 0 ? getLines([this.prog, ...optParts], indent, prefix) : [this.prog];
      } else {
        // Long program name: it gets a line of its own.
        const indent = ' '.repeat(prefix.length);
        lines = [this.prog, ...getLines(optParts, indent, null)];
      }
      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n\n`;
  }

  /** `format_help`: the usage block plus the `options:` section. */
  formatHelp(actions) {
    const invocations = actions.map(formatActionInvocation);
    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT_INCREMENT));
    const maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT),
    );
    const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
    const actionWidth = Math.max(helpPosition - INDENT_INCREMENT - 2, 1);
    const helpWidth = Math.max(this.width - helpPosition, 11);

    let text = `${this.formatUsage(actions)}options:\n`;
    actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        text += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
        return;
      }
      const helpLines = wrapText(action.help, helpWidth);
      if (invocation.length <= actionWidth) {
        text += `${' '.repeat(INDENT_INCREMENT)}${invocation.padEnd(actionWidth)}  ${helpLines[0]}\n`;
      } else {
        text += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
        text += `${' '.repeat(helpPosition)}${helpLines[0]}\n`;
      }
      for (const line of helpLines.slice(1)) {
        text += `${' '.repeat(helpPosition)}${line}\n`;
      }
    });

    // `HelpFormatter.format_help` collapses runs of blank lines and normalises
    // the surrounding ones.
    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

