/**
 * The slice of `argparse.ArgumentParser` this program relies on: long options
 * that each take one value, `-h/--help`, prefix matching, `--opt=value`, and
 * argparse's exact error reporting (usage on stderr, status 2).
 */

import { SystemExit } from '../python/errors.mjs';
import { PyException } from '../python/errors.mjs';
import { reprString } from '../python/repr.mjs';
import { writeStderr, writeStdout } from '../python/io.mjs';
import { HelpFormatter } from './formatter.mjs';
import { strType } from './types.mjs';

/** `argparse._negative_number_matcher`; `\d` spans all Unicode digits. */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

const PREFIX_CHARS = '-';

class Action {
  constructor({ optionStrings, dest, type, required, help, metavar, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.isHelp = isHelp;
    this.takesValue = !isHelp;
  }

  /** `argparse._get_action_name`: how the action is named in error messages. */
  get name() {
    return this.optionStrings.join('/');
  }
}

/** Raised by value conversion, reported by the parser as an exit-2 error. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(`argument ${action.name}: ${message}`);
    this.argparseMessage = `argument ${action.name}: ${message}`;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.add_argument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string|string[]} flags   e.g. `'--a'`
   * @param {object} options          `type`, `required`, `help`, `metavar`, `action`
   */
  add_argument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const isHelp = options.action === 'help';
    const action = new Action({
      optionStrings,
      dest,
      type: options.type ?? strType,
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? dest.toUpperCase(),
      isHelp,
    });
    this.actions.push(action);
    for (const optionString of optionStrings) this.optionStringActions.set(optionString, action);
    return action;
  }

  get formatter() {
    return new HelpFormatter(this.prog);
  }

  format_usage() {
    return this.#normalise(this.formatter.formatUsage(this.actions));
  }

  format_help() {
    return this.formatter.formatHelp(this.actions);
  }

  /** `HelpFormatter.format_help`'s trailing-newline normalisation. */
  #normalise(text) {
    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }

  print_usage(stream = writeStdout) {
    stream(this.format_usage());
  }

  print_help(stream = writeStdout) {
    stream(this.format_help());
  }

  /** `parser.exit`: optionally print a message, then raise `SystemExit`. */
  exit(status = 0, message = null) {
    if (message) writeStderr(message);
    throw new SystemExit(status);
  }

  /** `parser.error`: usage plus `prog: error: message` on stderr, status 2. */
  error(message) {
    this.print_usage(writeStderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /**
   * `_parse_optional`: decide whether a token is an option, a plain value, or
   * an option this parser does not know.
   */
  #classify(token) {
    if (token === '') return { kind: 'value' };
    if (!PREFIX_CHARS.includes(token[0])) return { kind: 'value' };
    if (this.optionStringActions.has(token)) {
      return { kind: 'option', action: this.optionStringActions.get(token), explicitArg: null };
    }
    if (Array.from(token).length === 1) return { kind: 'value' };
    if (token.includes('=')) {
      const separator = token.indexOf('=');
      const optionString = token.slice(0, separator);
      if (this.optionStringActions.has(optionString)) {
        return {
          kind: 'option',
          action: this.optionStringActions.get(optionString),
          explicitArg: token.slice(separator + 1),
        };
      }
    }
    const matches = this.#optionTuples(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return { kind: 'option', ...matches[0] };
    if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
    if (token.includes(' ')) return { kind: 'value' };
    return { kind: 'unknown' };
  }

  /** `_get_option_tuples`: abbreviations, plus `-oVALUE` style short options. */
  #optionTuples(token) {
    const result = [];
    const separator = token.indexOf('=');
    if (token.startsWith('--')) {
      const optionPrefix = separator >= 0 ? token.slice(0, separator) : token;
      const explicitArg = separator >= 0 ? token.slice(separator + 1) : null;
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push({ action, optionString, explicitArg });
      }
      return result;
    }
    // Single dash: either an abbreviation or a value glued to a short option.
    const shortOptionPrefix = token.slice(0, 2);
    const shortExplicitArg = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(token)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  /** `_get_value`: apply `type`, turning failures into an ArgumentError. */
  #convert(action, text) {
    try {
      return action.type(text);
    } catch (error) {
      if (error instanceof PyException) {
        throw new ArgumentError(action, `invalid ${action.type.typeName} value: ${reprString(text)}`);
      }
      throw error;
    }
  }

  #takeAction(action, namespace, value) {
    if (action.isHelp) {
      this.print_help(writeStdout);
      this.exit(0);
    }
    namespace[action.dest] = this.#convert(action, value);
  }

  /** `parse_known_args`: the namespace plus every token left unclaimed. */
  parse_known_args(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }
    const seen = new Set();
    const extras = [];
    let separatorSeen = false;
    let index = 0;

    try {
      while (index < argv.length) {
        const token = argv[index];
        if (separatorSeen) {
          extras.push(token);
          index += 1;
          continue;
        }
        if (token === '--') {
          // The first `--` both ends option parsing and, with no positionals
          // declared, stays behind as an unrecognised argument.
          separatorSeen = true;
          extras.push(token);
          index += 1;
          continue;
        }

        const classified = this.#classify(token);
        if (classified.kind !== 'option') {
          extras.push(token);
          index += 1;
          continue;
        }

        const { action, explicitArg } = classified;
        seen.add(action);
        if (explicitArg !== null && explicitArg !== undefined) {
          if (!action.takesValue) {
            this.error(`argument ${action.name}: ignored explicit argument ${reprString(explicitArg)}`);
          }
