  }

  get formatter() {
    return new HelpFormatter(this.prog);
  }

  format_usage() {
    return this.#normalise(this.formatter.formatUsage(this.actions));
  }

  format_help() {
    return this.formatter.formatHelp(this.actions);
  }

  /** `HelpFormatter.format_help`'s trailing-newline normalisation. */
  #normalise(text) {
    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }

  print_usage(stream = writeStdout) {
