/**
 * The interpreter/launcher wrapper around `main()`.
 *
 * An escaping exception is reported as a traceback on stderr followed by the
 * bootloader's own complaint, and the process exits 1; `SystemExit` (raised by
 * argparse) only carries its status.  `process.exitCode` is set rather than
 * calling `process.exit()` so buffered writes always reach the pipe.
 */

import { PyException, SystemExit } from './errors.mjs';
import { writeStderr } from './io.mjs';
import { formatTraceback } from './traceback.mjs';

/**
 * @param {object} options
 * @param {string} options.scriptStem  script name without extension
 * @param {object} options.moduleFrame the module level frame calling `main()`
 * @param {Function} options.main
 */
export function runFrozenScript({ scriptStem, moduleFrame, main }) {
  try {
    main();
  } catch (error) {
    if (error instanceof SystemExit) {
      process.exitCode = error.code;
      return;
    }
    if (error instanceof PyException) {
      error.pyTraceback.unshift(moduleFrame);
      writeStderr(formatTraceback(error));
      writeStderr(
        `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptStem}' ` +
          'due to unhandled exception!\n',
      );
      process.exitCode = 1;
      return;
    }
    throw error;
  }
}

