/**
 * `traceback.print_exception()` output.
 *
 * For every frame CPython prints the `File ...` line, then -- only when
 * `linecache` can actually find the source -- the stripped source line, then a
 * caret line marking the failing expression.  The carets come from the column
 * offsets recorded in the code object, mapped onto the line found on disk, and
 * are suppressed when the expression covers that whole line.
 */

import { getLine } from './linecache.mjs';

const HEADER = 'Traceback (most recent call last):';
const SOURCE_INDENT = '    ';

/** Python's `str.strip()` / `str.lstrip()` whitespace class. */
const WHITESPACE = /[\t\n\v\f\r \x1c\x1d\x1e\x1f\x85   -     　]/;

function stripPython(text) {
  let start = 0;
  let end = text.length;
  while (start < end && WHITESPACE.test(text[start])) start += 1;
  while (end > start && WHITESPACE.test(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

function leadingWhitespace(text) {
  let count = 0;
  while (count < text.length && WHITESPACE.test(text[count])) count += 1;
  return count;
}

const UTF8 = new TextEncoder();

/**
 * `traceback._byte_offset_to_character_offset`: a UTF-8 byte offset mapped to a
 * character offset, clamped to the end of the line.
 */
function byteOffsetToCharacterOffset(line, byteOffset) {
  let bytes = 0;
  let characters = 0;
  for (const character of line) {
    if (bytes >= byteOffset) return characters;
    bytes += UTF8.encode(character).length;
    characters += character.length;
  }
  return characters;
}

function formatFrame(frame) {
  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.func}`];
  const rawLine = getLine(frame.file, frame.line);
  const sourceLine = stripPython(rawLine);
  if (sourceLine === '') return lines;
  lines.push(`${SOURCE_INDENT}${sourceLine}`);

  if (frame.colno === null || frame.endColno === null) return lines;
  const stripped = leadingWhitespace(rawLine);
  const start = byteOffsetToCharacterOffset(rawLine, frame.colno) - stripped;
  const end = byteOffsetToCharacterOffset(rawLine, frame.endColno) - stripped;
  // Carets are only interesting when they do not span the whole statement.
  if (end - start < sourceLine.length && end > start && start >= 0) {
    lines.push(`${SOURCE_INDENT}${' '.repeat(start)}${'^'.repeat(end - start)}`);
  }
  return lines;
}

/**
 * @param {import('./errors.mjs').PyException} error
 * @returns {string} the traceback, newline terminated
 */
export function formatTraceback(error) {
  const lines = [HEADER];
  for (const frame of error.pyTraceback) lines.push(...formatFrame(frame));
  lines.push(error.exceptionLine);
  return `${lines.join('\n')}\n`;
}

