/**
 * Rendering of `traceback.print_exception()` output.
 *
 * CPython 3.11+ prints, for every frame, the source line and -- when the error
 * only covers part of that line -- a caret line marking the failing expression.
 * Frames whose source is unavailable (a library bundled without its sources)
 * are printed as the `File ...` line alone.
 */

const HEADER = 'Traceback (most recent call last):';

function formatFrame(frame) {
  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.func}`];
  if (frame.prefix !== null && frame.expr !== null) {
    lines.push(`${frame.prefix}${frame.expr}${frame.suffix}`);
    lines.push(`${' '.repeat(frame.prefix.length)}${'^'.repeat(frame.expr.length)}`);
  } else if (frame.text !== null) {
    lines.push(frame.text);
  }
  return lines;
}

/**
 * @param {import('./errors.mjs').PyException} error
 * @returns {string} the traceback, newline terminated
 */
export function formatTraceback(error) {
  const lines = [HEADER];
  for (const frame of error.pyTraceback) lines.push(...formatFrame(frame));
  lines.push(error.exceptionLine);
  return `${lines.join('\n')}\n`;
}

