/**
 * The slice of `argparse.ArgumentParser` this program relies on: long options
 * that each take one value, `-h/--help`, prefix matching, `--opt=value`, and
 * argparse's exact error reporting (usage on stderr, status 2).
 */

import { SystemExit } from '../python/errors.mjs';
import { PyException } from '../python/errors.mjs';
import { reprString } from '../python/repr.mjs';
import { writeStderr, writeStdout } from '../python/io.mjs';
import { HelpFormatter } from './formatter.mjs';
import { strType } from './types.mjs';

/** `argparse._negative_number_matcher`; `\d` spans all Unicode digits. */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

const PREFIX_CHARS = '-';

class Action {
  constructor({ optionStrings, dest, type, required, help, metavar, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.isHelp = isHelp;
    this.takesValue = !isHelp;
  }

  /** `argparse._get_action_name`: how the action is named in error messages. */
  get name() {
    return this.optionStrings.join('/');
  }
}

/** Raised by value conversion, reported by the parser as an exit-2 error. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(`argument ${action.name}: ${message}`);
    this.argparseMessage = `argument ${action.name}: ${message}`;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.add_argument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string|string[]} flags   e.g. `'--a'`
   * @param {object} options          `type`, `required`, `help`, `metavar`, `action`
   */
  add_argument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const isHelp = options.action === 'help';
    const action = new Action({
      optionStrings,
      dest,
      type: options.type ?? strType,
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? dest.toUpperCase(),
      isHelp,
    });
    this.actions.push(action);
    for (const optionString of optionStrings) this.optionStringActions.set(optionString, action);
    return action;
  }

  get formatter() {
    return new HelpFormatter(this.prog);
  }

  format_usage() {
    return this.#normalise(this.formatter.formatUsage(this.actions));
  }

  format_help() {
    return this.formatter.formatHelp(this.actions);
  }

