        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
      return result;
    }
    // Single dash: either an abbreviation or a value glued to a short option.
    const shortOptionPrefix = token.slice(0, 2);
    const shortExplicitArg = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(token)) {
        result.push({ action, optionString, sep: null, explicitArg: null });
      }
    }
    return result;
  }

  /** `_get_value`: apply `type`, turning failures into an ArgumentError. */
  #convert(action, text) {
    try {
      return action.type(text);
    } catch (error) {
      if (error instanceof PyException) {
        throw new ArgumentError(action, `invalid ${action.type.typeName} value: ${reprString(text)}`);
      }
      throw error;
    }
  }

  #takeAction(action, namespace, value) {
    if (action.isHelp) {
      this.print_help(writeStdout);
      this.exit(0);
    }
    namespace[action.dest] = this.#convert(action, value);
  }

  /** `parse_known_args`: the namespace plus every token left unclaimed. */
  parse_known_args(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }
    const seen = new Set();
    const extras = [];
    let separatorSeen = false;
    let index = 0;

    try {
      while (index < argv.length) {
        const token = argv[index];
        if (separatorSeen) {
          extras.push(token);
          index += 1;
          continue;
        }
        if (token === '--') {
          // The first `--` both ends option parsing and, with no positionals
          // declared, stays behind as an unrecognised argument.
          separatorSeen = true;
          extras.push(token);
          index += 1;
          continue;
        }

        const classified = this.#classify(token);
        if (classified.kind !== 'option') {
          extras.push(token);
          index += 1;
          continue;
        }

        const { action, explicitArg } = classified;
        seen.add(action);
        if (explicitArg !== null && explicitArg !== undefined) {
          if (!action.takesValue) {
            this.error(`argument ${action.name}: ignored explicit argument ${reprString(explicitArg)}`);
          }
          this.#takeAction(action, namespace, explicitArg);
          index += 1;
          continue;
        }
        if (!action.takesValue) {
          this.#takeAction(action, namespace, null);
          index += 1;
          continue;
        }

        const next = index + 1 < argv.length ? argv[index + 1] : null;
        const nextIsValue =
          next !== null && next !== '--' && this.#classify(next).kind === 'value';
        if (!nextIsValue) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        this.#takeAction(action, namespace, next);
        index += 2;
      }
    } catch (error) {
      if (error instanceof ArgumentError) this.error(error.argparseMessage);
      throw error;
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parse_args(argv) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

